      fontWeight: '700', fontSize: '0.78rem', whiteSpace: 'nowrap',
      transition: 'all 0.2s',
    }}
  >
    {downloadingModule === moduleKey ? 'Generating…' : '📥 Download PDF'}
  </button>
);

