  );
  const labels = [];
  const values = [];
  TERMS.forEach((term) => {
    EXAM_TYPES.forEach((et) => {
      const row = rows.find((r) => r.term === term && r.examType === et);
      labels.push(`${term.replace('Term ', 'T')} ${EXAM_LABELS[et]}`);
