const mongoose = require('mongoose');

const activeExamSchema = new mongoose.Schema(
  {
    _singleton: { type: String, default: 'global', unique: true },
    academicYear: { type: String, required: true },
    term: { type: String, enum: ['Term 1', 'Term 2', 'Term 3'], required: true }
  },
  { timestamps: true }
);

module.exports = mongoose.model('ActiveExam', activeExamSchema);

const express = require('express');
const router = express.Router();
const ActiveExam = require('../models/ActiveExam');
const { adminOnly } = require('../middleware/auth');

// GET /api/active-exam — any authenticated user can read
router.get('/', async (req, res) => {
  try {
    const config = await ActiveExam.findOne({ _singleton: 'global' });
    if (!config) return res.json({ academicYear: null, term: null });
    res.json({ academicYear: config.academicYear, term: config.term });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/active-exam — admin only, upserts the singleton
router.post('/', adminOnly, async (req, res) => {
  try {
    const { academicYear, term } = req.body;
    if (!academicYear || !term) {
      return res.status(400).json({ error: 'academicYear and term are required.' });
    }
    const config = await ActiveExam.findOneAndUpdate(
      { _singleton: 'global' },
      { academicYear: academicYear.toString(), term },
      { upsert: true, new: true, setDefaultsOnInsert: true }
    );
    res.json({ academicYear: config.academicYear, term: config.term });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

module.exports = router;

const BASE = '/api/active-exam';

const authHeaders = () => ({
  'Content-Type': 'application/json',
  Authorization: `Bearer ${localStorage.getItem('sv_token') || ''}`
});

const handle = async (res) => {
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error || `Request failed: ${res.statusText}`);
  }
  return res.json();
};

export const fetchActiveExam = () =>
  handle(fetch(BASE, { headers: authHeaders() }));

export const saveActiveExam = ({ academicYear, term }) =>
  handle(fetch(BASE, {
    method: 'POST',
    headers: authHeaders(),
    body: JSON.stringify({ academicYear, term })
  }));

